package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"sort"
	"strconv"
	"time"
)

// Task represents a single todo item.
type Task struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Done      bool      `json:"done"`
	CreatedAt time.Time `json:"created_at"`
}

const taskFile = "todos.json"

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(1)
	}

	cmd := os.Args[1]
	args := os.Args[2:]

	var err error
	switch cmd {
	case "add":
		err = cmdAdd(args)
	case "list":
		err = cmdList()
	case "done":
		err = cmdDone(args)
	case "rm":
		err = cmdRemove(args)
	default:
		usage()
		os.Exit(1)
	}

	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: todoapp <add|list|done|rm> [args]")
}

// loadTasks reads the task file, returning an empty slice if it does not exist.
func loadTasks() ([]Task, error) {
	data, err := os.ReadFile(taskFile)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return []Task{}, nil
		}
		return nil, err
	}
	if len(data) == 0 {
		return []Task{}, nil
	}
	var tasks []Task
	if err := json.Unmarshal(data, &tasks); err != nil {
		return nil, fmt.Errorf("parsing %s: %w", taskFile, err)
	}
	return tasks, nil
}

// saveTasks writes the task list to the task file.
func saveTasks(tasks []Task) error {
	data, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(taskFile, data, 0o644)
}

func nextID(tasks []Task) int {
	maxID := 0
	for _, t := range tasks {
		if t.ID > maxID {
			maxID = t.ID
		}
	}
	return maxID + 1
}

func findTask(tasks []Task, id int) (*Task, int) {
	for i := range tasks {
		if tasks[i].ID == id {
			return &tasks[i], i
		}
	}
	return nil, -1
}

func cmdAdd(args []string) error {
	if len(args) < 1 {
		return errors.New("add requires a title argument")
	}
	title := args[0]

	tasks, err := loadTasks()
	if err != nil {
		return err
	}

	tasks = append(tasks, Task{
		ID:        nextID(tasks),
		Title:     title,
		Done:      false,
		CreatedAt: time.Now(),
	})

	if err := saveTasks(tasks); err != nil {
		return err
	}

	fmt.Printf("added task %d: %s\n", tasks[len(tasks)-1].ID, title)
	return nil
}

func cmdList() error {
	tasks, err := loadTasks()
	if err != nil {
		return err
	}

	if len(tasks) == 0 {
		fmt.Println("no tasks")
		return nil
	}

	sort.Slice(tasks, func(i, j int) bool { return tasks[i].ID < tasks[j].ID })
	for _, t := range tasks {
		status := "[ ]"
		if t.Done {
			status = "[x]"
		}
		fmt.Printf("%s %d  %s\n", status, t.ID, t.Title)
	}
	return nil
}

func cmdDone(args []string) error {
	if len(args) < 1 {
		return errors.New("done requires a task id")
	}
	id, err := strconv.Atoi(args[0])
	if err != nil {
		return fmt.Errorf("invalid id %q", args[0])
	}

	tasks, err := loadTasks()
	if err != nil {
		return err
	}

	task, idx := findTask(tasks, id)
	if task == nil {
		return fmt.Errorf("task %d not found", id)
	}

	tasks[idx].Done = true
	if err := saveTasks(tasks); err != nil {
		return err
	}

	fmt.Printf("task %d marked done: %s\n", id, task.Title)
	return nil
}

func cmdRemove(args []string) error {
	if len(args) < 1 {
		return errors.New("rm requires a task id")
	}
	id, err := strconv.Atoi(args[0])
	if err != nil {
		return fmt.Errorf("invalid id %q", args[0])
	}

	tasks, err := loadTasks()
	if err != nil {
		return err
	}

	idx := -1
	for i, t := range tasks {
		if t.ID == id {
			idx = i
			break
		}
	}
	if idx == -1 {
		return fmt.Errorf("task %d not found", id)
	}

	removed := tasks[idx]
	tasks = append(tasks[:idx], tasks[idx+1:]...)
	if err := saveTasks(tasks); err != nil {
		return err
	}

	fmt.Printf("removed task %d: %s\n", id, removed.Title)
	return nil
}
